/* =================== 天气 =================== */
const WCODE={0:'晴',1:'晴',2:'多云',3:'阴',45:'雾',48:'雾',51:'小雨',53:'小雨',55:'雨',61:'小雨',63:'中雨',65:'大雨',71:'小雪',73:'雪',75:'大雪',80:'阵雨',81:'阵雨',82:'大阵雨',95:'雷雨',96:'雷雨'};
async function _weatherCoords(la,lo,placeName,manual){
  try{const w=await fetch('https://api.open-meteo.com/v1/forecast?latitude='+la+'&longitude='+lo+'&current=temperature_2m,weather_code,precipitation').then(r=>r.json());
    let place=placeName||'';
    if(!place){try{const g=await fetch('https://api.bigdatacloud.net/data/reverse-geocode-client?latitude='+la+'&longitude='+lo+'&localityLanguage=zh').then(r=>r.json());
      const parts=[g.principalSubdivision||g.city,g.locality,(g.localityInfo&&g.localityInfo.administrative&&g.localityInfo.administrative.slice(-1)[0]&&g.localityInfo.administrative.slice(-1)[0].name)];
      place=parts.filter((x,i,a)=>x&&a.indexOf(x)===i).join('·');}catch(e){}}
    const code=w.current.weather_code,desc=WCODE[code]||'未知';
    S.weather={place,temp:Math.round(w.current.temperature_2m),desc,rain:(w.current.precipitation>0||[51,53,55,61,63,65,80,81,82,95,96].indexOf(code)>=0),time:Date.now()};
    save();if(manual)toast(''+place+' '+desc+' '+S.weather.temp+'°C');if(cur().p==='settings'||cur().p==='home')render();return true;
  }catch(e){if(manual)toast('天气获取失败');return false;}}
async function weatherByCity(){const q=prompt('定位用不了？直接输你的城市（如 苏州、北京、Shanghai）：',(S.weather&&S.weather.place)||'');if(q==null)return;const city=q.trim();if(!city)return;toast('查询中…');
  try{const g=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(city)+'&count=1&language=zh&format=json').then(r=>r.json());
    if(!g||!g.results||!g.results.length){toast('没找到这个城市，换个写法再试');return;}
    const r0=g.results[0];const nm=[r0.admin1,r0.name].filter((x,i,a)=>x&&a.indexOf(x)===i).join('·')||city;
    await _weatherCoords(r0.latitude,r0.longitude,nm,true);
  }catch(e){toast('查询失败，检查网络');}}
function fetchWeather(manual){if(!navigator.geolocation){if(manual)weatherByCity();return;}
  navigator.geolocation.getCurrentPosition(p=>{_weatherCoords(p.coords.latitude,p.coords.longitude,'',manual);},()=>{if(manual)weatherByCity();},{timeout:8000,maximumAge:600000});}

